"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["29321"],{6413(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.calendario_vigente_ausente","status":422,"titulo":"N\xe3o h\xe1 calend\xe1rio de dias \xfateis vigente cadastrado"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.calendario_vigente_ausente","requisitos":["UNI-REQ-0116"],"oQueAconteceu":["O processo tem prazo cuja contagem distingue dia \xfatil de dia n\xe3o \xfatil, e n\xe3o h\xe1\\n**calend\xe1rio de dias \xfateis vigente** cadastrado.","Contar em dia \xfatil exige saber quais dias s\xe3o \xfateis. Quem responde isso \xe9 o\\ncalend\xe1rio: os feriados nacionais, mais os estaduais e municipais da localidade\\nque o processo declara. Sem ele, n\xe3o h\xe1 como determinar o instante em que o\\nprazo termina, e a publica\xe7\xe3o para em vez de aproximar em sil\xeancio.","A vers\xe3o publicada congela o **conte\xfado** do calend\xe1rio \u2014 a lista de dias n\xe3o\\n\xfateis vigente no momento da publica\xe7\xe3o \u2014, e n\xe3o apenas a constata\xe7\xe3o de que\\nhavia um. O identificador e a vers\xe3o do calend\xe1rio de origem ficam guardados ao\\nlado, como rastreio, e nunca s\xe3o relidos para recontar.","Guardar s\xf3 a refer\xeancia n\xe3o reproduz contagem nenhuma. O calend\xe1rio pode ganhar\\nvers\xe3o nova depois da publica\xe7\xe3o, e o calend\xe1rio que deixa de ser vigente pode ser\\nremovido do cadastro; nos dois casos, um recurso j\xe1 em curso fecharia num\\ninstante diferente do que a vers\xe3o prometeu, ou n\xe3o teria como ser recontado.\\nA vers\xe3o publicada \xe9 imut\xe1vel e n\xe3o admite completar depois o dado que sumiu.","Dependem do calend\xe1rio:","- **todo prazo de interposi\xe7\xe3o**, seja em dias \xfateis, seja em horas;\\n- o **prazo da 2\xaa inst\xe2ncia**, quando o recurso admite inst\xe2ncia superior, com as\\n  mesmas unidades e a mesma contagem do prazo de interposi\xe7\xe3o.","Um prazo que n\xe3o \xe9 de recurso, como o do per\xedodo de solicita\xe7\xe3o de isen\xe7\xe3o, n\xe3o\\ndepende do calend\xe1rio."],"comoResolver":["Cadastre um calend\xe1rio de dias \xfateis e coloque-o em vig\xeancia antes de publicar.\\nEle \xe9 dado institucional, compartilhado entre os certames \u2014 n\xe3o \xe9 configurado\\ndentro do processo seletivo.","Esta causa \xe9 distinta da do\\n[algoritmo de contagem n\xe3o declarado](/erros/uniplus.selecao.processo_seletivo.algoritmo_contagem_prazo_nao_declarado),\\ne a corre\xe7\xe3o \xe9 outra: l\xe1 falta a conven\xe7\xe3o que o edital escolhe, aqui falta o\\ndado que diz quais dias s\xe3o \xfateis. As duas podem faltar ao mesmo tempo, e cada\\numa \xe9 reportada por si."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);